      AND attname = 'mission_id' AND NOT attisdropped AND format_type(atttypid, atttypmod) = 'uuid')), false) THEN RAISE EXCEPTION 'SCHEMA_COLUMN_REQUIRED'; END IF; END;
BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conrelid = to_regclass('public.external_action_requests')
    AND c.conname = 'external_action_requests_workspace_mission_fkey' AND c.contype = 'f' AND c.convalidated
    AND c.confrelid = to_regclass('public.marketing_missions') AND c.confdeltype = 'r'
    AND (SELECT array_agg(attname::text ORDER BY k.n) FROM unnest(c.conkey) WITH ORDINALITY k(num,n)
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.num) = ARRAY['workspace_id','mission_id']
    AND (SELECT array_agg(attname::text ORDER BY k.n) FROM unnest(c.confkey) WITH ORDINALITY k(num,n)
      JOIN pg_attribute a ON a.attrelid = c.confrelid AND a.attnum = k.num) = ARRAY['workspace_id','id'])), false) THEN RAISE EXCEPTION 'TENANT_FOREIGN_KEY_REQUIRED'; END IF; END;
BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_index WHERE indexrelid = to_regclass('public.idx_mission_action_receipts_workspace_receipt_unique')
      AND indisunique AND indisvalid AND indisready AND indpred IS NULL AND indexprs IS NULL
      AND indrelid = to_regclass('public.mission_action_receipts') AND indnkeyatts = 2
      AND (SELECT array_agg(a.attname::text ORDER BY k.n) FROM unnest(indkey::smallint[]) WITH ORDINALITY k(num,n)
        JOIN pg_attribute a ON a.attrelid = indrelid AND a.attnum = k.num) = ARRAY['workspace_id','action_receipt_id'])), false) THEN RAISE EXCEPTION 'RECEIPT_UNIQUENESS_REQUIRED'; END IF; END;
BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang
      WHERE p.oid = to_regprocedure('public.update_mission_snapshot_atomic(uuid,uuid,integer,jsonb,text,text,uuid,text,text,text,jsonb,jsonb)') AND p.prorettype = 'jsonb'::regtype
      AND p.proargnames = ARRAY['p_workspace_id','p_mission_id','p_expected_snapshot_version','p_new_metadata','p_new_status','p_new_goal','p_new_receipt_id','p_actor_type','p_actor_id','p_event_name','p_event_payload','p_receipt_entry']::text[] AND p.pronargdefaults = 8
      AND p.prosecdef AND NOT p.proretset AND l.lanname = 'plpgsql'
      AND p.proconfig = ARRAY['search_path=public'] AND md5(p.prosrc) = '54df08ce8d6a6df9f717e4a178ba9480'
      AND has_function_privilege('service_role', p.oid, 'EXECUTE')
      AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
      AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE')
      AND NOT EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f',p.proowner))) a
        WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE')
      AND (SELECT count(*) FROM pg_proc other WHERE other.pronamespace = p.pronamespace AND other.proname = p.proname) = 1)), false) THEN RAISE EXCEPTION 'RPC_CONTRACT_OR_PRIVILEGE_DRIFT'; END IF; END;
BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang
      WHERE p.oid = to_regprocedure('public.create_mission_with_contract_atomic(uuid,text,text,text,text,text,text,text,text,jsonb,text,text,text,jsonb)') AND p.prorettype = 'jsonb'::regtype
      AND p.proargnames = ARRAY['p_workspace_id','p_trace_id','p_status','p_goal','p_strategy_summary','p_target_channel','p_target_audience','p_source_message_id','p_source_conversation_job_id','p_metadata','p_actor_type','p_actor_id','p_event_name','p_event_payload']::text[] AND p.pronargdefaults = 10
      AND p.prosecdef AND NOT p.proretset AND l.lanname = 'plpgsql'
      AND p.proconfig = ARRAY['search_path=public'] AND md5(p.prosrc) = '2accdb857f3c591e9a7770dc0692b25f'
      AND has_function_privilege('service_role', p.oid, 'EXECUTE')
      AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
