      AND NOT EXISTS (SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f',p.proowner))) a
        WHERE a.grantee = 0 AND a.privilege_type = 'EXECUTE')
      AND (SELECT count(*) FROM pg_proc other WHERE other.pronamespace = p.pronamespace AND other.proname = p.proname) = 1)), false) THEN RAISE EXCEPTION 'RPC_CONTRACT_OR_PRIVILEGE_DRIFT'; END IF; END;
