BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_class WHERE oid=to_regclass('public.first_post_publish_consumptions') AND relrowsecurity)), false) THEN RAISE EXCEPTION 'PUBLISH_CONSUMPTION_RLS_REQUIRED'; END IF; END;
BEGIN IF NOT COALESCE((NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid=to_regclass('public.first_post_publish_consumptions') AND contype='u')), false) THEN RAISE EXCEPTION 'PUBLISH_CONTENT_RETRY_CONSTRAINT'; END IF; END;
BEGIN IF NOT COALESCE((EXISTS (SELECT 1 FROM pg_index WHERE indexrelid=to_regclass('public.first_post_consumptions_content_idx') AND indisvalid AND indisready AND NOT indisunique)), false) THEN RAISE EXCEPTION 'PUBLISH_CONTENT_INDEX_REQUIRED'; END IF; END;
BEGIN IF NOT COALESCE((to_regprocedure('private.first_post_publish_key(jsonb,text)') IS NOT NULL AND to_regprocedure('public.save_meta_channel_connection(uuid,uuid,text,text,text,text,text,text[],timestamptz,timestamptz)') IS NOT NULL), false) THEN RAISE EXCEPTION 'PUBLISH_BASELINE_RPC_REQUIRED'; END IF; END;
RETURN jsonb_build_object('ready',true,'contract','9d37071271904333bea770eea800898b6c85270fea25b74ed6f1b4465a8d49ae');
